 saved.memories??=[];saved.relations??={};saved.city??={time:872,stories:[],npcStates:{},feed:[],economy:{budget:100000,transactions:0},tick:0};const city=saved.city;city.stories??=[];city.npcStates??={};city.feed??=[];city.economy??={budget:100000,transactions:0};
 const grids=[[460,640],[700,620],[970,670],[1170,1000],[1460,1020],[1740,1020],[1960,630],[2170,630],[500,960],[720,1020],[950,960],[1180,900],[1490,610],[1740,620],[1970,970],[2180,970],[470,1400],[740,1440],[990,1320],[1200,1450],[1500,1410],[1730,1470],[1940,1430],[2160,1420],[480,1580],[760,1560],[990,1560],[1210,1570],[1470,1570],[1740,1560],[1960,1580],[2200,1600]];
 for(let i=0;i<records.length;i++){const [name,age,job,topics,goal,past,quirk,loves,hates]=records[i],home=grids[i];chars.push({id:'citizen-'+i,name,role:`${job} · ${age} anos`,age,job,portrait:i+4,home:[...home],x:home[0],y:home[1],color:['#e1b17e','#b9a1d6','#91c3c3','#aec781','#cf9494','#8eafcf'][i%6],place:home[1]>1200?'Jardins da Maré':home[0]>1850?'Orla da Maré':home[0]<800?'Vila Aurora':'Centro',traits:[['Observador','Sociável','Criativo','Reservado'][i%4],['Persistente','Cuidadoso','Direto','Curioso'][Math.floor(i/4)%4],['Prático','Afetuoso','Autônomo','Bem-humorado'][Math.floor(i/8)%4]],interests:topics.split('|'),bio:[past,quirk,`Trabalha como ${job.toLowerCase()} em Porto Neon.`,`Seu objetivo atual é ${goal.toLowerCase()}.`,`Gosta especialmente de ${loves.replace('|',' e ')}.`,`Evita ${hates.replace('|',' e ')}.`,beliefs[i%8],'Avalia amizades pelo que a pessoa faz, não apenas pelo que promete.','Troca histórias e experiências com outros moradores ao longo do dia.'],values:['Reciprocidade e independência.','Honestidade e cuidado.','Criatividade e respeito.','Aprendizado e solidariedade.'][i%4],goal:goal+'.',boundary:'Não aceita humilhação nem contato físico sem consentimento.',schedule:'Manhã: trabalho · Tarde: necessidades e praça · Noite: descanso',needs:{...needsDefault,food:60+(i*7)%36,energy:55+(i*11)%40},mood:'Tranquilo',wallet:120+i*13,loves:loves.split('|'),hates:hates.split('|'),belief:beliefs[i%8],quirk,react:styles[i%4]});}
 chars.forEach((n,i)=>{n.react??=styles[[0,3,0,1][i]??i%4];n.needs={...needsDefault,...n.needs};n.loves??=[n.interests[0],n.interests[1],'gentileza'];n.hates??=['humilhação','desonestidade','agressões'];n.belief??=beliefs[i%8];n.quirk??=n.bio[5];n.knowledge=[{topic:n.interests[0],level:'Experiência prática',detail:n.bio[0]},{topic:n.interests[1],level:'Interesse pessoal',detail:n.bio[1]},{topic:n.interests[2],level:'Aprendendo',detail:'Aprende em conversas e experiências na cidade.'}];n.preferences={food:['comida caseira','pão fresco','frutas','massas'][i%4],music:['rock','samba','jazz','música eletrônica'][i%4],leisure:n.interests[1],conversation:i%2?'Conversas calmas, sem pressão':'Humor e perguntas curiosas'};n.smokes=i%5===1;n.cigarettes=n.smokes?3:0;n.activity='Observando o bairro';n.knownStories=[];n.experience=0;n.learnedInterests=[];n.grievances={};n.compliments=[`Admiro o seu conhecimento de ${n.interests[0]}.`,`Você faz diferença no bairro com seu trabalho.`,`Gosto da sua dedicação a ${n.interests[1]}.`,`Seu jeito de ouvir as pessoas é especial.`];n.insults=[`Seu trabalho não vale nada.`,`Você não entende nada de ${n.interests[0]}.`,`Seu sonho é uma perda de tempo.`,`Você é um idiota.`];const old=city.npcStates[n.id];if(old){for(const key of ['x','y','wallet','needs','mood','knownStories','experience','learnedInterests','grievances','cigarettes'])if(old[key]!==undefined)n[key]=old[key];n.needs={...needsDefault,...n.needs};}if(!city.stories.find(s=>s.id==='seed-'+n.id)){const st={id:'seed-'+n.id,kind:'joke',text:jokes[i%jokes.length],origin:n.id,created:Date.now(),holders:[n.id],via:{[n.id]:{from:n.id,hops:0}},tokens:[]};city.stories.push(st);n.knownStories.push(st.id)}});
 const byId=id=>chars.find(n=>n.id===id);
 function relationship(p,n){const r=ctx.relation(p,n);r.scores??={};r.hurts??=[];r.turns??=0;r.lastReward??={};r.history??=[];return r;}
 function remember(p,n,text,kind='conversation'){ctx.addMemory(p,n,text,kind)}
 function publish(n,p,text,kind='event',valence=0){if(p&&!p.remember)return null;const st={id:'story-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),kind,text:String(text).slice(0,420),origin:n.id,created:Date.now(),holders:[n.id],via:{[n.id]:{from:n.id,hops:0}},tokens:p?[p.token]:[],player:p?.name,subject:p?.token,valence};city.stories.push(st);n.knownStories.push(st.id);city.stories=city.stories.slice(-700);n.knownStories=n.knownStories.slice(-90);return st;}
 function feed(text){city.feed.unshift({text,time:Date.now()});city.feed=city.feed.slice(0,35)}
 function reward(p,n,key,amount){const r=relationship(p,n),last=r.lastReward[key]||0;if(Date.now()-last<60000)return 0;r.lastReward[key]=Date.now();r.trust=cap(r.trust+amount,-100,100);n.needs.happiness=cap(n.needs.happiness+amount);p.needs.happiness=cap(p.needs.happiness+Math.max(1,amount/2));return amount;}
 function profile(p,n){const r=relationship(p,n);const learned=n.knownStories.map(id=>city.stories.find(s=>s.id===id)).filter(Boolean);const {grievances,route,engagedUntil,target,...safe}=n;return {...safe,relationship:r,reaction:reactions[n.react],memories:saved.memories.filter(m=>m.token===p.token&&m.npc===n.id).slice(-25),stories:learned.map(s=>({id:s.id,kind:s.kind,text:s.text,origin:byId(s.origin)?.name||'Morador',source:byId(s.via?.[n.id]?.from)?.name||'Morador',hops:s.via?.[n.id]?.hops||0,reach:s.holders.length})).slice(-15),ownGrievance:n.grievances[p.token]||null,worldAge:city.tick||0};}
 function emitResult(p,n,text,userText,changes={}){const r=relationship(p,n);r.met=true;r.turns++;r.trust=cap(r.trust,-100,100);r.affection=cap(r.affection);p.needs.social=cap(p.needs.social+3);n.needs.social=cap(n.needs.social+2);n.engagedUntil=Date.now()+90000;if(p.remember){if(userText){remember(p,n,userText);r.history.push({from:'you',text:userText,time:Date.now()})}r.history.push({from:'npc',text,time:Date.now()});r.history=r.history.slice(-100)}return {text,emotion:n.mood,profile:profile(p,n),...changes};}
 function reaction(p,n,severity,reason){const r=relationship(p,n);r.trust=cap(r.trust-12*severity,-100,100);r.hurts.push({reason,time:Date.now(),severity});r.hurts=r.hurts.slice(-25);n.needs.happiness=cap(n.needs.happiness-severity*12);p.reputation-=severity*3;if(p.remember){n.grievances[p.token]={reason,time:Date.now(),severity:Math.max(severity,n.grievances[p.token]?.severity||0)};remember(p,n,`${p.name}: ${reason}`,'event');publish(n,p,`${p.name} ${reason} contra ${n.name}.`,'event',-severity)}
 if(n.react==='lawful'){p.wanted=cap(p.wanted+1,0,3);p.heat=Date.now()+50000;n.mood='Alarmado';return 'Afaste-se. Vou chamar a polícia. Isso ficou registrado e não vou esquecer tão cedo.'}
 if(n.react==='avoidant'){n.fleeUntil=Date.now()+30000;n.engagedUntil=0;n.mood='Assustado';return 'Não quero nenhum conflito. Vou me afastar e procurar um lugar seguro.'}
 if(n.react==='fighter'){p.health=cap(p.health-14*severity);n.mood='Furioso';if(p.health<=0)return respawn(p,false);return `Você passou do limite! A briga causou ${14*severity} de dano. Se afaste.`}
 p.health=cap(p.health-30*severity);n.mood='Extremamente hostil';p.wanted=cap(p.wanted+1,0,3);p.heat=Date.now()+45000;if(p.health<=0)return respawn(p,true);return `O conflito ficou perigoso: você sofreu ${30*severity} de dano. Afaste-se antes que termine em morte no jogo.`;}
 function respawn(p,death){p.health=70;p.cash=Math.max(0,p.cash-120);p.wanted=0;p.car=false;p.x=1775;p.y=580;p._relocate={x:p.x,y:p.y};p.needs.happiness=30;return death?'O confronto terminou em morte simulada, sem cena gráfica. Você reapareceu na clínica e perdeu até R$ 120. O personagem continua lembrando do conflito.':'Você foi nocauteado e levado à clínica. Saúde recuperada parcialmente; atendimento de até R$ 120.'}
 function actions(p,n,action,detail){const r=relationship(p,n);let text='',spoken='';
 if(action==='compliment'){const i=cap(Number(detail)||0,0,n.compliments.length-1);spoken=n.compliments[i];const amount=reward(p,n,'compliment-'+i,6);r.affection=cap(r.affection+(amount?2:0));n.mood=amount?'Valorizado':n.mood;text=amount?`Fico feliz que você repare nisso. ${n.quirk} Seu reconhecimento me fez bem.`:'Você já me disse isso há pouco. Prefiro sinceridade a repetir o mesmo elogio.';}
 else if(action==='insult'){const i=cap(Number(detail)||0,0,n.insults.length-1);spoken=n.insults[i];r.insults++;text=r.insults===1?(r.trust-=12,n.needs.happiness=cap(n.needs.happiness-12),n.mood='Ofendido','Isso foi ofensivo. Podemos discordar, mas não aceito humilhação.'):reaction(p,n,r.insults>=3?3:2,'insultou e humilhou');if(r.insults===1&&p.remember){n.grievances[p.token]={reason:'primeiro insulto',severity:1,time:Date.now()};remember(p,n,`${p.name} fez um insulto pessoal.`,'event')}}
 else if(action==='apology'){spoken='Quero pedir desculpas pelo que fiz.';if(r.hurts.length||r.insults){reward(p,n,'apology',5);r.insults=Math.max(0,r.insults-1);n.mood='Cauteloso';text='Ouvi seu pedido. Não vou apagar o que aconteceu. Se você mudar suas atitudes e me der tempo, talvez eu volte a confiar.'}else text='Está tudo bem entre nós. Obrigado por se preocupar.'}
 else if(action==='gift'){spoken='Trouxe uma flor para você.';if(!p.inventory.flower)text='Você não tem flores na mochila. O Mercado Sol vende algumas.';else{p.inventory.flower--;reward(p,n,'gift',12);r.affection=cap(r.affection+6);n.mood='Acolhido';text='Que gesto gentil. Gostei de você ter lembrado de mim.';publish(n,p,`${p.name} presenteou ${n.name}.`,'event',2)}}
 else if(action==='hug'){spoken='Posso te dar um abraço?';if(r.trust<25||n.needs.happiness<35)text='Ainda não me sinto à vontade. Obrigado por perguntar antes.';else{reward(p,n,'hug',4);p.needs.social=cap(p.needs.social+15);text='Pode, sim. É bom ter alguém em quem confiar.'}}
 else if(action==='phone'){spoken='Podemos trocar números?';if(r.trust>=20&&n.needs.happiness>=35&&!n.grievances[p.token]?.severity){r.phone=true;text='Claro! Salvei meu contato no seu celular. Podemos conversar de longe.'}else if(r.trust>=40&&n.needs.happiness>=50){r.phone=true;text='Nossa relação melhorou. Podemos trocar números, mas ainda tenho alguns limites.'}else text='Prefiro conhecer você melhor. Preciso estar de bom humor e confiar em você para passar meu número.'}
 else if(action==='borrowPhone'){spoken='Pode me emprestar seu celular para ligar?';if(r.trust>=30&&n.needs.happiness>=40){text='Pode fazer uma ligação rápida, comigo aqui. Você ganhou uma chamada de resgate sem custo.';p.freeCall=true}else text='Não me sinto confortável emprestando meu celular agora. Isso exige confiança e um bom momento.'}
 else if(action==='cigarette'){spoken='Você tem um cigarro?';if(!n.smokes)text='Não fumo, então não tenho cigarro. Se quiser uma pausa, podemos só conversar.';else if(r.trust<15||n.needs.happiness<40)text='Prefiro não compartilhar agora. Não estou à vontade.';else if(n.cigarettes<1)text='Os meus acabaram.';else{n.cigarettes--;p.inventory.cigarette=(p.inventory.cigarette||0)+1;text='Tenho um. Guardei na sua mochila. É só um item fictício; não melhora sua saúde.'}}
 else if(action==='romance'){spoken='Você gostaria de sair comigo?';if(r.trust>=45&&r.affection>=15&&n.needs.happiness>=45){reward(p,n,'romance',4);r.affection=cap(r.affection+8);n.mood='Contente';text='Quero, sim. Vamos conhecer melhor um ao outro, sem pressão.'}else text='Não quero isso agora. Preciso de confiança, afinidade e vontade — amizade não obriga ninguém a aceitar romance.'}
 else if(action==='attack'){spoken='Agredir o personagem.';text=reaction(p,n,3,'cometeu uma agressão')}
 else if(action==='humiliate'){spoken='Urinar no personagem (ação não gráfica).';if(p.needs.bladder>80)text='Você não precisa ir ao banheiro agora. Essa ação humilhante não foi realizada.';else{p.needs.bladder=100;p.needs.hygiene=cap(p.needs.hygiene-35);n.needs.hygiene=cap(n.needs.hygiene-30);p.needs.happiness=cap(p.needs.happiness-15);text=reaction(p,n,4,'humilhou de forma grave')}}
 else if(action==='rob'){spoken='Tentar assaltar o personagem.';if(r.trust<-50||n.react==='dangerous'){text=reaction(p,n,4,'tentou assaltar')}else{const take=Math.min(n.wallet,70);n.wallet-=take;p.cash+=take;const consequence=reaction(p,n,3,'assaltou');text=`Você tomou R$ ${take}. ${consequence}`}}
 else if(action==='favor'){spoken='Você precisa de algum favor?';if(p.job)text='Termine seu trabalho atual antes de assumir outra responsabilidade.';else if(r.trust<25||n.needs.happiness<30)text='Ainda não tenho confiança para pedir um favor. Vamos nos conhecer um pouco mais.';else if(Date.now()-(r.lastFavor||0)<120000)text='Por enquanto já resolvi o que precisava. Podemos conversar.';else{const target=chars[(chars.indexOf(n)+7)%chars.length];p.job={kind:'favor',giver:n.id,target:target.id,title:`Favor para ${n.name.split(' ')[0]}`,desc:`Leve um recado a ${target.name}. Interaja ao chegar ao marcador.`,x:target.x,y:target.y,reward:65,stage:'deliver'};r.lastFavor=Date.now();text=`Você pode levar um recado até ${target.name}? Confio em você. O destino está marcado; vou te pagar R$ 65.`}}
 else if(action==='joke'){spoken='Conte uma piada que você ouviu.';const known=city.stories.filter(s=>n.knownStories.includes(s.id)&&s.kind==='joke');const chosen=known.sort((a,b)=>b.created-a.created)[r.turns%Math.min(3,known.length)]||known[0];text=chosen?`${chosen.origin===n.id?'Tenho uma:':`Ouvi de ${byId(chosen.via?.[n.id]?.from)?.name||'alguém do bairro'}: `} ${chosen.text}`:'Ainda não ouvi nenhuma piada nova.';reward(p,n,'joke',2);n.mood='Bem-humorado'}
 else if(action==='police'){spoken='Como peço ajuda?';text='Abra o celular e ligue 190. Se estiver ferido, o resgate atende no 192.'}
 else if(['help','music','steal'].includes(action)){return {mini:action};}
 else return emitResult(p,n,'Essa ação não está disponível. Escolha uma das opções do painel.');
 return emitResult(p,n,text,spoken);}
 function talk(p,n,input){const r=relationship(p,n),t=norm(input),idx=r.turns;let text;const doAction=(action,detail)=>{const out=actions(p,n,action,detail);if(p.remember){const h=r.history;if(h.length>=2)h[h.length-2].text=input;const m=saved.memories.filter(m=>m.token===p.token&&m.npc===n.id&&m.type==='conversation').slice(-1)[0];if(m)m.text=input;}return out;};const all=n.interests.concat(n.learnedInterests||[]);const topic=all.find(v=>t.includes(norm(v)));
 if(/^(contar piada|piada|minha piada)\s*:/i.test(input)){const joke=input.slice(input.indexOf(':')+1).trim();if(joke.length<12)return emitResult(p,n,'Conte a piada inteira depois de “Piada:”.',input);if(/idiota|ameac|matar|humilh/.test(norm(joke)))return emitResult(p,n,'Não gosto de piadas usadas para humilhar ou ameaçar alguém.',input);if(p.remember){publish(n,p,joke,'joke',1);reward(p,n,'sharejoke',5);n.mood='Divertido';text='Gostei! Vou guardar essa e talvez contar a alguém quando nos encontrarmos. Pode levar um tempo para circular pelo bairro.'}else text='Podemos rir agora, mas sua memória está desativada: não vou guardar nem espalhar a piada.';}
 else if(/\b(desculpa|desculpe|perdao)\b|sinto muito/.test(t))return doAction('apology');
 else if(/\b(idiota|imbecil|burro|inutil|otario)\b|nao vale nada|perda de tempo|nao entende nada/.test(t))return doAction('insult',Math.min(r.insults,3));
 else if(/\b(admiro|talento|parabens)\b|voce e incrivel|seu trabalho e bom|gosto de voce/.test(t))return doAction('compliment',topic?Math.max(0,n.interests.indexOf(topic))%4:0);
 else if(/emprest.*celular|usar.*celular/.test(t))return doAction('borrowPhone');
 else if(/telefone|seu numero|trocar numero/.test(t))return doAction('phone');
 else if(/cigarro/.test(t))return doAction('cigarette');
 else if(/sair comigo|namorar|romance/.test(t))return doAction('romance');
 else if(/favor|missao|trabalho|emprego/.test(t)){text=r.trust>=25?'Tenho um favor para alguém em quem confio. Abra Ações → Pedir missão de amizade. Também há trabalhos livres no mural.':'Vamos criar confiança primeiro para favores pessoais. Enquanto isso, abra Trabalhos no menu para entregas e serviços.';}
 else if(/piada|engracad/.test(t))return doAction('joke');
 else if(/odeia|detesta|nao gosta/.test(t)){text=`O que mais me incomoda é ${n.hates.join(' e ')}. ${n.boundary}`;}
 else if(/gosta|prefer|adora|ama/.test(t)&&!topic){text=`Gosto muito de ${n.loves.join(', ')}. Para comer, prefiro ${n.preferences.food}; para relaxar, ${n.preferences.leisure}. E você?`;}
 else if(/crenca|religia|acredita|valores/.test(t)){text=n.belief+' '+n.values;}
 else if(/historia|biografia|quem e voce|sobre voce/.test(t)){text=n.bio[idx%n.bio.length]+' '+n.goal;}
 else if(/lembra|memoria|falei/.test(t)){const m=saved.memories.filter(m=>m.token===p.token&&m.npc===n.id&&m.type==='conversation').slice(-2)[0];text=n.grievances[p.token]?`Lembro especialmente do conflito: ${n.grievances[p.token].reason}. Um pedido de desculpas não apaga isso, mas ações consistentes podem mudar nossa relação.`:m?`Lembro de você dizer “${m.text.slice(0,180)}”. Quer retomar esse assunto?`:'Ainda temos poucas lembranças juntos. Podemos começar uma história hoje.';}
 else if(/boato|fofoca|novidade|bairro|ouviu/.test(t)){const st=city.stories.filter(s=>n.knownStories.includes(s.id)&&s.kind==='event').sort((a,b)=>b.created-a.created)[0];text=st?`Ouvi de ${byId(st.via?.[n.id]?.from)?.name||'um vizinho'}: ${st.text} ${st.valence<0?'Prefiro ter cuidado e ouvir os envolvidos.':'É bom ver gentileza circulando.'}`:`Ainda não recebi relatos novos. Converso com os vizinhos quando nos encontramos. Meu plano hoje é ${n.goal.toLowerCase()}`;}
 else if(/como (voce )?(esta|vai)|tudo bem|precisa de algo/.test(t)){const [need,value]=Object.entries(n.needs).sort((a,b)=>a[1]-b[1])[0];text=value<45?`Estou com ${n.mood.toLowerCase()}. Preciso cuidar de ${needNames[need].toLowerCase()} antes de continuar meu dia.`:`Estou ${n.mood.toLowerCase()}. ${n.activity}. E você, como está?`;}
 else if(/\b(triste|sozinho|cansado|ansioso|medo)\b/.test(t)){text=['Parece um dia difícil. Quer contar o que aconteceu? Posso ouvir, sem tentar adivinhar o que você sente.','Podemos fazer uma pausa. Você prefere conversar ou descansar um pouco?','Não tenho todas as respostas, mas valorizo você ter compartilhado isso.'][idx%3];reward(p,n,'support',3);n.mood='Atento';}
 else if(topic){const j=all.indexOf(topic);text=[`Meu interesse por ${topic} tem uma história: ${n.bio[j%n.bio.length]} Você tem alguma experiência com isso?`,`Quando penso em ${topic}, lembro do meu objetivo: ${n.goal} É um assunto que ainda quero aprender melhor.`,`Uma coisa que valorizo em ${topic} é a troca de experiências. ${n.quirk} O que mais chama sua atenção?`][(r.scores[topic]||0)%3];r.scores[topic]=(r.scores[topic]||0)+1;reward(p,n,'topic-'+topic,4);n.mood='Interessado';n.experience++;}
 else if(/^(oi|ola|e ai|bom dia|boa tarde|boa noite|opa)[!?.\s]*$/.test(t)){text=r.met?`Oi, ${p.name}. ${n.grievances[p.token]?'Ainda precisamos reconstruir a confiança.':`Bom ver você. Hoje estou ${n.mood.toLowerCase()}.`}`:`Oi, ${p.name}. Sou ${n.name.split(' ')[0]}, ${n.role.toLowerCase()}. Gosto de ${n.interests[0]} e ${n.interests[1]}.`;}
 else if(/^sim[!.\s]*$|^nao[!.\s]*$/.test(t)){text=t.startsWith('sim')?'Entendi. Me conte um exemplo ou escolha um dos nossos assuntos para continuar.':'Tudo bem. Podemos mudar de assunto. Quer falar da sua vida ou saber mais sobre mim?';}
 else if(/banheiro|fome|sono|higiene/.test(t)){text='Na Casa e no Café há banheiro. Em casa você também pode descansar e tomar banho. Comer, dormir e cuidar da higiene ajudam a manter o humor.';}
 else{text=[`Não sei responder com precisão sobre “${input.slice(0,80)}”. Conheço melhor ${n.interests.slice(0,2).join(' e ')}. Quer explorar um desses assuntos?`,`Quero entender melhor. Isso é uma pergunta sobre mim, um plano ou algo que aconteceu? Posso conversar sobre preferências, histórias e notícias do bairro.`,`Ainda não tenho conhecimento sobre esse assunto. Se quiser compartilhar uma piada que eu possa guardar, escreva “Piada:” e o texto. Ou pergunte sobre ${n.interests[idx%n.interests.length]}.`][idx%3];}
 return emitResult(p,n,text,input);}
 const needNames={food:'Alimentação',energy:'Sono',social:'Social',hygiene:'Higiene',happiness:'Felicidade',bladder:'Banheiro'};
